class Solution {
    public int numSubmat(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int[] height = new int[cols];
        int answer = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                height[c] = mat[r][c] == 0 ? 0 : height[c] + 1;
            }
            for (int right = 0; right < cols; right++) {
                int minHeight = height[right];
                for (int left = right; left >= 0 && minHeight > 0; left--) {
                    minHeight = Math.min(minHeight, height[left]);
                    answer += minHeight;
                }
            }
        }
        return answer;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int numSubmat(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int[] height = new int[cols];
        int answer = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                height[c] = mat[r][c] == 0 ? 0 : height[c] + 1;
            }

            Deque<int[]> stack = new ArrayDeque<>();
            int rowCount = 0;
            for (int c = 0; c < cols; c++) {
                int width = 1;
                while (!stack.isEmpty() && stack.peek()[0] >= height[c]) {
                    int[] top = stack.pop();
                    rowCount -= top[0] * top[1];
                    width += top[1];
                }
                stack.push(new int[] {height[c], width});
                rowCount += height[c] * width;
                answer += rowCount;
            }
        }
        return answer;
    }
}

import java.util.Arrays;

class Solution {
    public int numSubmat(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int answer = 0;
        for (int top = 0; top < rows; top++) {
            int[] allOne = new int[cols];
            Arrays.fill(allOne, 1);
            for (int bottom = top; bottom < rows; bottom++) {
                int run = 0;
                for (int c = 0; c < cols; c++) {
                    allOne[c] &= mat[bottom][c];
                    if (allOne[c] == 1) {
                        run++;
                        answer += run;
                    } else {
                        run = 0;
                    }
                }
            }
        }
        return answer;
    }
}

class Solution {
    public int numSubmat(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int[][] width = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (mat[r][c] == 1) {
                    width[r][c] = (c == 0 ? 0 : width[r][c - 1]) + 1;
                }
            }
        }

        int answer = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int minWidth = width[r][c];
                for (int up = r; up >= 0 && minWidth > 0; up--) {
                    minWidth = Math.min(minWidth, width[up][c]);
                    answer += minWidth;
                }
            }
        }
        return answer;
    }
}
